$Instance = '{{ProfiseeInstanceName}}'
$Action = 'FindService'
$AppFilter = ''
# Profisee instance discovery (CrewChief packs). Every step that finds the Windows service of a Profisee instance or acts
# on its IIS application pools carries this same text after three lines naming the instance, the action and the
# application filter. It is generated from packs\tools\instance-discovery.ps1.txt (instance_steps.py); never edit it in
# a workload. It runs ON the application server in Windows PowerShell (the WebAdministration module).
# Several Profisee instances (and versions) can live side by side on one server, so nothing is matched on a name or a
# name prefix alone:
#   - the instance's applications are /<instance> and everything under /<instance>/ (whole path segments, so instance
#     'Profisee' never catches /Profisee2 or /Profisee-qa);
#   - its pools are the application pools those applications use; a built-in pool, or a pool that also serves an
#     application of something else, is never touched (and is named in the output);
#   - its Windows service is the one whose program lies in the installed Profisee folder that holds the instance's
#     IIS application (the deepest product folder of the uninstall entries, or a version folder under
#     Program Files\Profisee\Master Data Maestro Server, that contains /<instance>'s physical path); when another
#     instance shares that folder, the installer's name form '... (<instance>)' decides; when no product folder holds
#     the instance, only that name form is used.
$ErrorActionPreference = 'Stop'
$CcBuiltInPools = @('DefaultAppPool', 'Classic .NET AppPool', '.NET v2.0', '.NET v2.0 Classic', '.NET v4.5', '.NET v4.5 Classic',
    'ASP.NET v4.0', 'ASP.NET v4.0 Classic')
$CcIc = [StringComparison]::OrdinalIgnoreCase

function Test-CcUnder([string]$Path, [string]$Folder) {
    if (-not $Path -or -not $Folder) { return $false }
    $f = $Folder.TrimEnd('\')
    return $Path.TrimEnd('\').Equals($f, $CcIc) -or $Path.StartsWith($f + '\', $CcIc)
}

function Get-CcCommonDepth([string]$A, [string]$B) {
    $x = $A.TrimEnd('\').Split('\')
    $y = $B.TrimEnd('\').Split('\')
    $n = 0
    while ($n -lt $x.Count -and $n -lt $y.Count -and $x[$n].Equals($y[$n], $CcIc)) { $n++ }
    return $n
}

function Get-CcProgramPath([string]$CommandLine) {
    if (-not $CommandLine) { return '' }
    if ($CommandLine -match '^\s*"([^"]+)"') { return $Matches[1] }
    if ($CommandLine -match '^\s*(.+?\.exe)(\s|$)') { return $Matches[1] }
    return $CommandLine.Trim()
}

function Test-CcNamedFor($Service, [string]$Instance) {
    $rx = '\(' + [regex]::Escape($Instance) + '\)\s*$'
    return ([string]$Service.Name -match $rx) -or ([string]$Service.DisplayName -match $rx)
}

function Test-CcInstancePath([string]$AppPath, [string]$Instance) {
    $root = '/' + $Instance
    return $AppPath.Equals($root, $CcIc) -or $AppPath.StartsWith($root + '/', $CcIc)
}

function Get-CcInstanceNames($Inventory) {
    @($Inventory.Apps | Where-Object { [string]$_.Path -match '^/[^/]+$' } | ForEach-Object { ([string]$_.Path).Substring(1) } | Sort-Object -Unique)
}

function Get-CcInventory {
    # The real server: IIS applications (site root '/' included, for the shared-pool check), Windows services and the
    # folders installed Profisee products live in.
    Import-Module WebAdministration
    $apps = New-Object System.Collections.Generic.List[object]
    foreach ($site in @(Get-ChildItem 'IIS:\Sites')) {
        $sitePool = [string]$site.applicationPool
        $apps.Add([pscustomobject]@{ Site = [string]$site.Name; Path = '/'; Pool = $sitePool
                PhysicalPath = [Environment]::ExpandEnvironmentVariables([string]$site.physicalPath) })
        foreach ($a in @(Get-WebApplication -Site $site.Name)) {
            $pool = [string]$a.applicationPool
            if (-not $pool) { $pool = $sitePool }
            $apps.Add([pscustomobject]@{ Site = [string]$site.Name; Path = [string]$a.path; Pool = $pool
                    PhysicalPath = [Environment]::ExpandEnvironmentVariables([string]$a.PhysicalPath) })
        }
    }
    $services = @(Get-CimInstance -ClassName Win32_Service | ForEach-Object {
            [pscustomobject]@{ Name = [string]$_.Name; DisplayName = [string]$_.DisplayName; PathName = [string]$_.PathName; State = [string]$_.State } })
    $keys = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*', 'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*'
    $folders = @(Get-ItemProperty -Path $keys -ErrorAction SilentlyContinue |
        Where-Object { [string]$_.DisplayName -match 'Profisee|Maestro' -and $_.InstallLocation } |
        ForEach-Object { ([string]$_.InstallLocation).TrimEnd('\') })
    foreach ($pf in @($env:ProgramFiles, ${env:ProgramFiles(x86)})) {
        if (-not $pf) { continue }
        $server = Join-Path $pf 'Profisee\Master Data Maestro Server'
        if (Test-Path -LiteralPath $server) { $folders += @(Get-ChildItem -LiteralPath $server -Directory | ForEach-Object { $_.FullName }) }
    }
    [pscustomobject]@{ Computer = $env:COMPUTERNAME; Apps = $apps.ToArray(); Services = $services
        InstallFolders = @($folders | Where-Object { $_ } | Sort-Object -Unique) }
}

function Select-CcInstanceService($Inventory, [string]$Instance) {
    # Returns the instance's one Windows service, $null when it has none, or throws (instance missing, more than one
    # service, or a service another instance in the same folder may own).
    $roots = @($Inventory.Apps | Where-Object { ([string]$_.Path).Equals('/' + $Instance, $CcIc) })
    if ($roots.Count -eq 0) {
        throw "No IIS application /$Instance on $($Inventory.Computer) (instances there: $((Get-CcInstanceNames $Inventory) -join ', ')). Check the instance name in reference data."
    }
    $folders = @($roots | ForEach-Object { [string]$_.PhysicalPath } | Where-Object { $_ } | Sort-Object -Unique)
    if ($folders.Count -ne 1) {
        throw "IIS application /$Instance on $($Inventory.Computer) has $($folders.Count) physical folders ($($folders -join '; ')); cannot tell which install it belongs to."
    }
    $instFolder = $folders[0]
    $installed = @($Inventory.InstallFolders | Where-Object { Test-CcUnder $instFolder $_ } | Sort-Object { $_.TrimEnd('\').Length } -Descending)
    $mine = @()
    $unsure = @()
    if ($installed.Count -gt 0) {
        $folder = $installed[0]
        $rivals = @($Inventory.Apps | Where-Object {
                ([string]$_.Path) -match '^/[^/]+$' -and -not ([string]$_.Path).Equals('/' + $Instance, $CcIc) -and (Test-CcUnder ([string]$_.PhysicalPath) $folder)
            } | ForEach-Object { [pscustomobject]@{ Name = ([string]$_.Path).Substring(1); Folder = [string]$_.PhysicalPath } })
        foreach ($s in @($Inventory.Services)) {
            $program = Get-CcProgramPath $s.PathName
            if (-not (Test-CcUnder $program $folder)) { continue }
            $depth = Get-CcCommonDepth $program $instFolder
            if (@($rivals | Where-Object { (Get-CcCommonDepth $program $_.Folder) -gt $depth }).Count -gt 0) { continue }
            $tied = @($rivals | Where-Object { (Get-CcCommonDepth $program $_.Folder) -eq $depth })
            if ($tied.Count -eq 0 -or (Test-CcNamedFor $s $Instance)) { $mine += $s; continue }
            if (@($tied | Where-Object { Test-CcNamedFor $s $_.Name }).Count -gt 0) { continue }
            $unsure += $s
        }
    }
    else {
        $mine = @($Inventory.Services | Where-Object { Test-CcNamedFor $_ $Instance })
    }
    if ($unsure.Count -gt 0) {
        throw "Instance $Instance on $($Inventory.Computer) shares its installed folder with other instances and these services could belong to either: $(($unsure | ForEach-Object { "'$($_.Name)' ($($_.PathName))" }) -join ', ')."
    }
    if ($mine.Count -gt 1) {
        $named = @($mine | Where-Object { Test-CcNamedFor $_ $Instance })
        if ($named.Count -eq 1) { $mine = $named }
    }
    if ($mine.Count -gt 1) {
        throw "More than one Windows service belongs to instance $Instance on $($Inventory.Computer): $(($mine | ForEach-Object { "'$($_.Name)' ($($_.PathName))" }) -join ', '). Remove the stale one."
    }
    if ($mine.Count -eq 1) { return $mine[0] }
    return $null
}

function Select-CcInstancePools($Inventory, [string]$Instance, [string]$AppFilter) {
    # One object per pool the instance's applications use: Pool, Apps (paths), Skip (why it is not touched, or blank).
    $ours = @($Inventory.Apps | Where-Object { Test-CcInstancePath ([string]$_.Path) $Instance })
    $chosen = $ours
    if ($AppFilter) { $chosen = @($ours | Where-Object { ([string]$_.Path).Equals('/' + $Instance + '/' + $AppFilter, $CcIc) }) }
    if ($chosen.Count -eq 0) {
        $what = if ($AppFilter) { "/$Instance/$AppFilter" } else { "/$Instance" }
        throw "No IIS application $what on $($Inventory.Computer) (instances there: $((Get-CcInstanceNames $Inventory) -join ', ')). Check the instance name in reference data."
    }
    foreach ($name in @($chosen | ForEach-Object { [string]$_.Pool } | Where-Object { $_ } | Sort-Object -Unique)) {
        $paths = @($chosen | Where-Object { ([string]$_.Pool).Equals($name, $CcIc) } | ForEach-Object { [string]$_.Path })
        $others = @($Inventory.Apps | Where-Object { ([string]$_.Pool).Equals($name, $CcIc) -and -not (Test-CcInstancePath ([string]$_.Path) $Instance) } |
            ForEach-Object { "$($_.Site)$($_.Path)" })
        $skip = ''
        if (@($CcBuiltInPools | Where-Object { $_.Equals($name, $CcIc) }).Count -gt 0) { $skip = 'a built-in IIS pool' }
        elseif ($others.Count -gt 0) { $skip = "also serves $($others -join ', ')" }
        [pscustomobject]@{ Pool = $name; Apps = $paths; Skip = $skip }
    }
}

function Invoke-CcPoolAction([string]$Name, [string]$Action) {
    $prev = [string](Get-WebAppPoolState -Name $Name).Value
    if ($Action -eq 'Recycle') {
        if ($prev -eq 'Stopped') { Start-WebAppPool -Name $Name } else { Restart-WebAppPool -Name $Name }
    }
    elseif ($prev -ne 'Started') { Start-WebAppPool -Name $Name }
    $deadline = (Get-Date).AddSeconds(120)
    while ([string](Get-WebAppPoolState -Name $Name).Value -ne 'Started') {
        if ((Get-Date) -gt $deadline) { throw "Application pool '$Name' did not reach Started within 120 seconds (it was $prev)." }
        Start-Sleep -Milliseconds 500
    }
    "$prev -> Started"
}

function Invoke-CcInstanceStep([string]$Instance, [string]$Action, [string]$AppFilter, $Inventory, [scriptblock]$PoolAction) {
    $Instance = $Instance.Trim().Trim('/')
    if (-not $Instance) { throw 'The instance name resolved blank (ProfiseeInstanceName).' }
    if (-not $Inventory) { $Inventory = Get-CcInventory }
    if ($Action -eq 'FindService') {
        # The output IS the run parameter (outputParameterName): the service's short name, or nothing.
        $s = Select-CcInstanceService $Inventory $Instance
        if ($s) { Write-Output ([string]$s.Name) }
        return
    }
    if ($Action -ne 'Recycle' -and $Action -ne 'Start') { throw "Unknown action '$Action' (FindService, Recycle or Start)." }
    if (-not $PoolAction) { $PoolAction = { param($Name, $Act) Invoke-CcPoolAction $Name $Act } }
    $pools = @(Select-CcInstancePools $Inventory $Instance $AppFilter)
    $use = @($pools | Where-Object { -not $_.Skip })
    $scope = if ($AppFilter) { "application /$Instance/$AppFilter" } else { "instance /$Instance" }
    "$($Inventory.Computer): $scope uses $($pools.Count) application pool(s); $($Action.ToLower()) $($use.Count):"
    foreach ($p in @($pools | Where-Object { $_.Skip })) { "  not touched: '$($p.Pool)' ($($p.Skip))" }
    if ($use.Count -eq 0) { throw "No application pool of $scope on $($Inventory.Computer) may be touched (see the lines above)." }
    foreach ($p in $use) {
        $state = & $PoolAction $p.Pool $Action
        "  $($Action.ToLower()) '$($p.Pool)' (serves $($p.Apps -join ', ')): $state"
    }
}

# ---- run ----
Invoke-CcInstanceStep -Instance $Instance -Action $Action -AppFilter $AppFilter

